(function() {
        const inputKeywords = document.getElementById('input-keywords');
        const inputSite = document.getElementById('input-site');
        const inputFiletype = document.getElementById('input-filetype');
        const inputExact = document.getElementById('input-exact');
        const inputIntitle = document.getElementById('input-intitle');
        const inputInurl = document.getElementById('input-inurl');
        const inputExclude = document.getElementById('input-exclude');
        const inputAfter = document.getElementById('input-after');
        const inputBefore = document.getElementById('input-before');

        const queryPreview = document.getElementById('query-preview');
        const charCountBadge = document.getElementById('char-count-badge');
        const copyQueryBtn = document.getElementById('copy-query-btn');
        const copyBtnText = document.getElementById('copy-btn-text');
        const launchGoogleBtn = document.getElementById('launch-google-btn');
        const launchDdgBtn = document.getElementById('launch-ddg-btn');
        const resetBuilderBtn = document.getElementById('reset-builder-btn');

        function buildQuery() {
            const parts = [];

            const keywords = inputKeywords.value.trim();
            if (keywords) parts.push(keywords);

            const exact = inputExact.value.trim();
            if (exact) parts.push('"' + exact + '"');

            const site = inputSite.value.trim();
            if (site) parts.push('site:' + site);

            const filetype = inputFiletype.value.trim();
            if (filetype) parts.push('filetype:' + filetype);

            const intitle = inputIntitle.value.trim();
            if (intitle) {
                if (intitle.includes(' ')) {
                    parts.push('intitle:"' + intitle + '"');
                } else {
                    parts.push('intitle:' + intitle);
                }
            }

            const inurl = inputInurl.value.trim();
            if (inurl) parts.push('inurl:' + inurl);

            const exclude = inputExclude.value.trim();
            if (exclude) {
                const words = exclude.split(/\s+/);
                words.forEach(w => {
                    if (w) parts.push('-' + w);
                });
            }

            const after = inputAfter.value;
            if (after) parts.push('after:' + after);

            const before = inputBefore.value;
            if (before) parts.push('before:' + before);

            const query = parts.join(' ');
            queryPreview.textContent = query || '(Fill in operators above or select a preset)';
            charCountBadge.textContent = (query.length) + ' chars';
            return query;
        }

        const inputs = [
            inputKeywords, inputSite, inputFiletype, inputExact,
            inputIntitle, inputInurl, inputExclude, inputAfter, inputBefore
        ];

        inputs.forEach(input => {
            input.addEventListener('input', buildQuery);
        });

        // Presets
        document.getElementById('preset-academic').addEventListener('click', () => {
            inputKeywords.value = 'quantum coherence';
            inputSite.value = 'edu';
            inputFiletype.value = 'pdf';
            inputExact.value = 'double-blind';
            inputIntitle.value = '';
            inputInurl.value = '';
            inputExclude.value = '';
            inputAfter.value = '';
            inputBefore.value = '';
            buildQuery();
        });

        document.getElementById('preset-audit').addEventListener('click', () => {
            inputKeywords.value = 'DB_PASSWORD';
            inputSite.value = 'example.com';
            inputFiletype.value = 'env';
            inputExact.value = '';
            inputIntitle.value = '';
            inputInurl.value = '';
            inputExclude.value = 'github.com';
            inputAfter.value = '';
            inputBefore.value = '';
            buildQuery();
        });

        document.getElementById('preset-index').addEventListener('click', () => {
            inputKeywords.value = '';
            inputSite.value = '';
            inputFiletype.value = '';
            inputExact.value = 'parent directory';
            inputIntitle.value = 'index of /';
            inputInurl.value = '';
            inputExclude.value = '';
            inputAfter.value = '';
            inputBefore.value = '';
            buildQuery();
        });

        document.getElementById('preset-reddit').addEventListener('click', () => {
            inputKeywords.value = 'best mechanical keyboard switches';
            inputSite.value = 'reddit.com';
            inputFiletype.value = '';
            inputExact.value = '';
            inputIntitle.value = '';
            inputInurl.value = 'comments';
            inputExclude.value = '';
            inputAfter.value = '';
            inputBefore.value = '';
            buildQuery();
        });

        document.getElementById('preset-datasets').addEventListener('click', () => {
            inputKeywords.value = 'global climate temperature anomalies';
            inputSite.value = '.gov';
            inputFiletype.value = 'csv';
            inputExact.value = '';
            inputIntitle.value = '';
            inputInurl.value = '';
            inputExclude.value = '';
            inputAfter.value = '';
            inputBefore.value = '';
            buildQuery();
        });

        // Copy Query
        copyQueryBtn.addEventListener('click', () => {
            const query = buildQuery();
            if (!query) return;
            navigator.clipboard.writeText(query).then(() => {
                copyBtnText.textContent = 'Copied!';
                copyQueryBtn.classList.add('bg-emerald-600');
                setTimeout(() => {
                    copyBtnText.textContent = 'Copy Query';
                    copyQueryBtn.classList.remove('bg-emerald-600');
                }, 2000);
            });
        });

        // Launch in Google
        launchGoogleBtn.addEventListener('click', () => {
            const query = buildQuery();
            if (!query) return;
            const url = 'https://www.google.com/search?q=' + encodeURIComponent(query);
            window.open(url, '_blank', 'noopener,noreferrer');
        });

        // Launch in DuckDuckGo
        launchDdgBtn.addEventListener('click', () => {
            const query = buildQuery();
            if (!query) return;
            const url = 'https://duckduckgo.com/?q=' + encodeURIComponent(query);
            window.open(url, '_blank', 'noopener,noreferrer');
        });

        // Reset
        resetBuilderBtn?.addEventListener('click', () => {
            inputs.forEach(input => input.value = '');
            buildQuery();
        });

        // Initial default load
        document.getElementById('preset-academic').click();
    })();
